// Strip HTML down to readable text, classify content_type, extract dates,
// and chunk it. No third-party scraping API required.
// Mirrors scripts/ingest.py so logic stays in sync.
const url = $('Set Input (edit URL here)').first().json.url;
const html = $json.data || $json.body || '';

function extractTitle(h) {
  const m = h.match(/<title[^>]*>([^<]*)<\/title>/i);
  return m ? m[1].trim() : url;
}

function htmlToText(h) {
  // Drop script/style/nav/footer/header blocks entirely
  let cleaned = h.replace(/<(script|style|nav|footer|header|noscript|svg)[^>]*>[\s\S]*?<\/\1>/gi, ' ');
  // Strip remaining tags
  cleaned = cleaned.replace(/<[^>]+>/g, '\n');
  // Decode a few common entities
  cleaned = cleaned.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
  // Collapse whitespace
  cleaned = cleaned.replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n').trim();
  return cleaned;
}

const title = extractTitle(html);
const markdown = htmlToText(html);

function classify(u) {
  if (u.includes('/event')) return 'event';
  if (u.includes('/news')) return 'news';
  if (u.includes('/industr')) return 'industry';
  if (u.includes('/about') || u.includes('/company')) return 'company';
  return 'main_page';
}

const MONTHS = { jan:1, feb:2, mar:3, apr:4, may:5, jun:6, jul:7, aug:8, sep:9, oct:10, nov:11, dec:12 };

function extractDates(text) {
  // Handles numeric dates (2026-09-14) AND the real Machines Italia
  // event format: '14/19 Sep 2026' or '16 Sep 2026' (day, optional
  // day-range, month name, year). A range yields both start+end dates.
  const found = new Set();

  const numericRe = /\b(20\d{2})[-\/](\d{1,2})[-\/](\d{1,2})\b/g;
  let m;
  while ((m = numericRe.exec(text)) !== null) {
    const [_, y, mo, d] = m;
    found.add(`${y}-${mo.padStart(2,'0')}-${d.padStart(2,'0')}`);
  }

  const eventRe = /\b(\d{1,2})(?:\/(\d{1,2}))?\s+([A-Za-z]{3,9})\s+(\d{4})\b/g;
  while ((m = eventRe.exec(text)) !== null) {
    const [_, day1, day2, monthName, year] = m;
    const mn = MONTHS[monthName.toLowerCase().slice(0,3)];
    if (!mn) continue;
    for (const day of [day1, day2]) {
      if (!day) continue;
      found.add(`${year}-${String(mn).padStart(2,'0')}-${day.padStart(2,'0')}`);
    }
  }

  return Array.from(found).sort();
}

function extractCity(text) {
  const patterns = [
    /(?:location|venue|city)\s*[:\-]\s*([A-Za-zÀ-ÿ' -]{2,50})/i,
    /(?:held in|takes place in|located in)\s+([A-Za-zÀ-ÿ' -]{2,50})/i
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);

    if (match) {
      return match[1].trim();
    }
  }
  return null;
}

function chunkText(text, size = 3000, overlap = 300) {
  if (text.length <= size) return [text];
  const chunks = [];
  let start = 0;
  while (start < text.length) {
    chunks.push(text.slice(start, start + size));
    start += size - overlap;
  }
  return chunks;
}

const contentType = classify(url);
const dates = extractDates(markdown);
const locationCity = extractCity(markdown);
const contentHash = '';

const baseMetadata = {
  url,
  title,
  content_type: contentType,
  language: 'en',
  scraped_at: new Date().toISOString(),
  content_hash: contentHash,
};
if (contentType === 'event' && dates.length) {
  baseMetadata.event_start_date = new Date(dates[0]).getTime();
  baseMetadata.event_end_date = new Date(dates[dates.length - 1]).getTime();

  if (locationCity) {
    baseMetadata.location_city = locationCity;
  }
} else if (contentType === 'news' && dates.length) {
  baseMetadata.published_date = dates[0];
}

const slug = url.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 80);
const chunks = chunkText(markdown);

return chunks.map((chunkTextValue, i) => ({
  json: {
    ...baseMetadata,
    chunk_index: i,
    chunk_text: chunkTextValue,
    vector_id: `${contentType}:${slug}:${i}`,
  },
}));

// Combine the embedding with the chunk's metadata into a Pinecone vector.
const chunkData = $('Classify & Chunk').item.json;
const embedding = $json.data[0].embedding;

return [{
  json: {
    id: chunkData.vector_id,
    values: embedding,
    metadata: {
      url: chunkData.url,
      title: chunkData.title,
      content_type: chunkData.content_type,
      language: chunkData.language,
      scraped_at: chunkData.scraped_at,
      content_hash: chunkData.content_hash,
      chunk_index: chunkData.chunk_index,
      text: chunkData.chunk_text,
      ...(chunkData.event_start_date && { event_start_date: chunkData.event_start_date }),
      ...(chunkData.event_end_date && { event_end_date: chunkData.event_end_date }),
      ...(chunkData.published_date && { published_date: chunkData.published_date }),
      ...(chunkData.location_city && { location_city: chunkData.location_city }),
    },
  },
}];

// Collect all vectors from all items into ONE upsert call (Pinecone prefers batching).
const allItems = $input.all();
const vectors = allItems.map(item => item.json);
return [{ json: { vectors } }];
